//! A profile's output before headers are attached.

use http::StatusCode;

use super::artifact::StreamKind;

/// Who "produced" a response; decides which headers it carries.
#[derive(Clone, Debug)]
pub enum Origin {
    /// A file served straight off disk by the front server.
    Static { ext: String, mtime: i64 },
    /// A response produced by the application (sessions, framework headers).
    App { session: bool },
    /// A page generated by the front server itself (errors, autoindex).
    Server,
}

#[derive(Clone)]
pub struct Doc {
    pub status: StatusCode,
    pub origin: Origin,
    pub content_type: Option<String>,
    pub head: Vec<u8>,
    /// Streamed continuation: kind and number of blocks.
    pub stream: Option<(StreamKind, u64)>,
    pub tail: Vec<u8>,
    pub extra_headers: Vec<(String, String)>,
}

impl Doc {
    pub fn new(origin: Origin, content_type: Option<&str>, head: impl Into<Vec<u8>>) -> Self {
        Doc {
            status: StatusCode::OK,
            origin,
            content_type: content_type.map(str::to_string),
            head: head.into(),
            stream: None,
            tail: Vec::new(),
            extra_headers: Vec::new(),
        }
    }

    pub fn status(mut self, status: StatusCode) -> Self {
        self.status = status;
        self
    }

    pub fn streamed(mut self, kind: StreamKind, blocks: u64, tail: impl Into<Vec<u8>>) -> Self {
        self.stream = Some((kind, blocks));
        self.tail = tail.into();
        self
    }

    pub fn header(mut self, name: &str, value: impl Into<String>) -> Self {
        self.extra_headers.push((name.to_string(), value.into()));
        self
    }
}

/// Extension of the request path (`/a/b.sql.gz` -> `gz`), lowercased.
pub fn ext_of(path: &str) -> String {
    let file = path.rsplit('/').next().unwrap_or("");
    match file.rfind('.') {
        Some(i) if i + 1 < file.len() => file[i + 1..].to_ascii_lowercase(),
        _ => String::new(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn extensions() {
        assert_eq!(ext_of("/a/b.SQL"), "sql");
        assert_eq!(ext_of("/a/b.sql.gz"), "gz");
        assert_eq!(ext_of("/.env"), "env");
        assert_eq!(ext_of("/dir/"), "");
        assert_eq!(ext_of("/file."), "");
    }
}
